import {
  PLAYWRIGHT_FIXTURES_EXPORTS,
  playwrightFixturesCommonjs,
  playwrightFixturesModule,
} from "@testmaster/domain";

/**
 * The runner harness fixtures (`secrets`, `profileRequest`, `profilePage`) for a plain host. They
 * are generated by the same `@testmaster/domain` source the runner stages for imported code, so the
 * exported project cannot drift from the runner's semantics; only where the values come from
 * differs. Imported Playwright code keeps its authored `@playwright/test` import: the exported
 * project installs this directory as the package `@playwright/test`, which re-exports the pinned
 * stock package (installed under an npm alias) with the three fixtures added, so a test that uses
 * none of them runs exactly as under stock Playwright.
 */
export const FIXTURES_DIRECTORY = "testmaster-fixtures";
/** Install name of the stock `@playwright/test` that the fixtures package extends. */
export const STOCK_PACKAGE = "playwright-test-stock";
/** The Playwright pinned by the exported npm projects (their lock integrity hashes are this version's). */
export const PLAYWRIGHT_VERSION = "1.63.0";
export const PROFILE_STORAGE_STATE_ENV = "TESTMASTER_PROFILE_STORAGE_STATE";
export const PROFILE_HEADERS_ENV = "TESTMASTER_PROFILE_HEADERS";
export const SECRET_ENV_PREFIX = "SECRET_";

export const fixturesPackageJson = {
  name: "@playwright/test",
  version: "0.0.0",
  private: true,
  exports: PLAYWRIGHT_FIXTURES_EXPORTS,
  dependencies: { [STOCK_PACKAGE]: `npm:@playwright/test@${PLAYWRIGHT_VERSION}` },
};

/**
 * Where a plain host gets the values the runner receives from its host: `secrets.get(name)` reads
 * `SECRET_<name>`; the auth profile session is a Playwright storage-state file (named by an
 * environment variable) and a JSON object of header credentials, scoped to the BASE_URL origin.
 */
const hostValues = String.raw`const { readFileSync } = require("node:fs");
const SECRET_PREFIX = ${JSON.stringify(SECRET_ENV_PREFIX)};
const STATE_ENV = ${JSON.stringify(PROFILE_STORAGE_STATE_ENV)};
const HEADERS_ENV = ${JSON.stringify(PROFILE_HEADERS_ENV)};
function secretValue(name) {
  if (typeof name !== "string") throw new Error("A secret name must be a string");
  const value = process.env[SECRET_PREFIX + name];
  if (value === undefined)
    throw new Error("Secret " + JSON.stringify(name.slice(0, 100)) + " is not set: export the environment variable " + SECRET_PREFIX + name.slice(0, 100));
  return value;
}
function originOf(baseURL) {
  if (!baseURL) throw new Error("BASE_URL must be set: the auth profile session is only sent to that origin");
  return new URL(baseURL).origin;
}
function cookieAppliesTo(cookie, origin) {
  if (typeof cookie.domain === "string" && cookie.domain) {
    const domain = cookie.domain.replace(/^\./, "").toLowerCase();
    const host = new URL(origin).hostname;
    return host === domain || host.endsWith("." + domain);
  }
  return typeof cookie.url === "string" && new URL(cookie.url).origin === origin;
}
function storageStateFor(origin) {
  const file = process.env[STATE_ENV];
  if (!file) return undefined;
  const state = JSON.parse(readFileSync(file, "utf8"));
  const scoped = {
    cookies: (state.cookies || []).filter((cookie) => cookieAppliesTo(cookie, origin)),
    origins: (state.origins || []).filter((entry) => entry.origin === origin),
  };
  return scoped.cookies.length > 0 || scoped.origins.length > 0 ? scoped : undefined;
}
function headersFromEnv() {
  const raw = process.env[HEADERS_ENV];
  if (!raw) return {};
  const headers = {};
  for (const [name, value] of Object.entries(JSON.parse(raw))) {
    if (typeof value !== "string") throw new Error(HEADERS_ENV + " must be a JSON object of header names to string values");
    headers[name.toLowerCase()] = value;
  }
  return headers;
}
function sessionFor(fixture, baseURL) {
  const origin = originOf(baseURL);
  const storageState = storageStateFor(origin);
  const headers = headersFromEnv();
  if (!storageState && Object.keys(headers).length === 0)
    throw new Error("The " + fixture + " fixture needs the environment's auth profile session: set " + STATE_ENV + " to a Playwright storage-state file with cookies or web storage for " + origin + " (or " + HEADERS_ENV + " to a JSON object of header credentials)");
  return { storageState, headers, origins: [origin] };
}`;

export const fixturesCommonjs = playwrightFixturesCommonjs({
  realModule: STOCK_PACKAGE,
  preamble: hostValues,
});
export const fixturesModule = playwrightFixturesModule({ realModule: STOCK_PACKAGE });
